import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

        if dim == 0:
            input_idx_expr = "k * stride0 + x * stride1 + y * stride2"
            output_shape_code = "out_dim0 = size1; out_dim1 = size2;"
        elif dim == 1:
            input_idx_expr = "x * stride0 + k * stride1 + y * stride2"
            output_shape_code = "out_dim0 = size0; out_dim1 = size2;"
        elif dim == 2:
            input_idx_expr = "x * stride0 + y * stride1 + k * stride2"
            output_shape_code = "out_dim0 = size0; out_dim1 = size1;"
        else:
            raise ValueError("Invalid reduction dimension")

        cuda_source = f"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void product_reduce_kernel(
    const float* input,
    float* output,
    int size0, int size1, int size2,
    int stride0, int stride1, int stride2,
    int out_dim0, int out_dim1,
    int out_stride0, int out_stride1,
    int size_reduce
) {{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= out_dim0 * out_dim1) return;

    int x = idx / out_dim1;
    int y = idx % out_dim1;

    float product = 1.0f;
    for (int k = 0; k < size_reduce; ++k) {{
        int input_idx = {input_idx_expr};
        product *= input[input_idx];
    }}
    output[x * out_stride0 + y * out_stride1] = product;
}}

torch::Tensor product_reduce_cuda(torch::Tensor input, int size_reduce) {{
    auto sizes = input.sizes();
    int size0 = sizes[0], size1 = sizes[1], size2 = sizes[2];
    auto strides = input.strides();
    int stride0 = strides[0], stride1 = strides[1], stride2 = strides[2];

    int out_dim0, out_dim1;
    {output_shape_code}

    auto output = torch::empty({{out_dim0, out_dim1}}, input.options());

    int out_stride0 = output.stride(0), out_stride1 = output.stride(1);
    const int block_size = 256;
    int grid_size = (out_dim0 * out_dim1 + block_size - 1) / block_size;

    product_reduce_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size0, size1, size2,
        stride0, stride1, stride2,
        out_dim0, out_dim1,
        out_stride0, out_stride1,
        size_reduce
    );

    return output;
}}
"""

        cpp_source = "torch::Tensor product_reduce_cuda(torch::Tensor input, int size_reduce);"

        self.custom_op = load_inline(
            name=f'product_reduce_{dim}',
            cpp_sources=cpp_source,
            cuda_sources=cuda_source,
            functions=['product_reduce_cuda'],
            verbose=False
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.custom_op.product_reduce_cuda(x, x.size(self.dim))
